-- Seed the Trades Physics content layer (program = 'trades').
-- Generated from src/data/trades-curriculum.ts. Idempotent: upsert by key.
-- Equivalent to: npx tsx scripts/seed-trades-curriculum.ts --commit

on conflict (id) do update set name = excluded.name, description = excluded.description, order_index = excluded.order_index, program = excluded.program;

on conflict (slug) do update set statement = excluded.statement, domain = excluded.domain, unit_id = excluded.unit_id, content_strand = excluded.content_strand, standard_refs = excluded.standard_refs, order_index = excluded.order_index, program = excluded.program;

on conflict (slug) do update set unit_id = excluded.unit_id, prompt = excluded.prompt, rubric = excluded.rubric, program = excluded.program;
