insert into public.units (id, name, description, order_index, program) values
  ('trades-1', 'Unit 1: Length & Tolerance — The Fieldhouse Wall', 'Measure it. Draw it. What the number on the material actually means.', 1, 'trades'),
  ('trades-2', 'Unit 2: Plumb, Level, Square, Slope', 'Gravity gives you one reference line free. Square you have to build.', 2, 'trades'),
  ('trades-3', 'Unit 3: Load', 'Live load, dead load, and where a hole does least harm.', 3, 'trades'),
  ('trades-4', 'Unit 4: Pressure', 'Flow = difference divided by resistance. Open systems and closed ones.', 4, 'trades'),
  ('trades-5', 'Unit 5: Heat', 'R-value, thermal bridging, and which side of the insulation a pipe goes on.', 5, 'trades'),
  ('trades-6', 'Unit 6: Electrical', 'Voltage drop, bonding, and why the wire gets fatter as the run gets longer.', 6, 'trades')
