insert into public.mastery_tasks (slug, unit_id, prompt, rubric, program) values
  ('tr.u1.mastery-as-built', 'trades-1', 'You are handed a drawing of one bay of the fieldhouse wall and the services on it. Walk it first and write the scope. Then verify the drawing, decide what is in and what is out, write an inspection another tradesman could act on, and produce an as-built of the bay as it really is.', '{"science": {"description": "Measurements correct, instrument suited to the precision required, recorded to the right fraction. Nominal and actual sizes handled correctly."}, "reasoning": {"description": "In-and-out calls follow from the numbers actually taken. Uncertainty is stated as a number, not a feeling."}, "communication": {"description": "Another tradesman could build from the as-built without asking a single question. Scale stated, nominal materials named in a note."}, "transfer": {"description": "Holds up on a real job. Planted errors caught; the consequence of being out of tolerance is named."}}'::jsonb, 'trades'),
  ('tr.u2.mastery-route-the-fall', 'trades-2', 'You are given a bay section, a fixture, and the point where the drain has to connect. Walk a real bay first and write the scope. Then route it, prove the fall, and show what it costs the framing — or prove that it cannot be done as drawn and state exactly what has to change and by how much.', '{"science": {"description": "The fall arithmetic is right and the depths used are actual sizes, not nominal ones."}, "reasoning": {"description": "The resolution follows from the student''s own numbers, and the easy wrong answer (reduce the fall) is rejected for a stated reason."}, "communication": {"description": "A tradesman could build from the plan and section without asking anything: fall called out, both end elevations dimensioned, bore located, scale stated."}, "transfer": {"description": "The student names what their decision costs another trade. ''It cannot be done as drawn'' is fully correct when proved."}}'::jsonb, 'trades')
